func codeFromKey(key Key) (int, bool) {
	end := len(key)
	start := end
	for start > 0 && key[start-1] >= '0' && key[start-1] <= '9' {
		start--
	}
	if start == end || start == 0 || key[start-1] != '_' {
		return 0, false
	}
	code := 0
	for i := start; i < end; i++ {
		code = code*10 + int(key[i]-'0')
	}
	return code, true
}

