func keyToMessage(key Key) *Message {
	code, ok := codeFromKey(key)
	if !ok {
		return nil
	}
	index := indexByCode[code&16383]
	if index == 0 {
		return nil
	}
	message := &messages[index-1]
	if message.key == key {
		return message
	}
	return nil
}
